+    BOOST_CHECK_EQUAL(entries, 2);
+    BOOST_REQUIRE_EQUAL(messages.size(), 1U);
+    BOOST_CHECK_EQUAL(messages.begin()->second, 1);
+    created.reset();
+    BOOST_CHECK_EQUAL(destroyed, 1);
