+    std::atomic<int> entries{0};
+    Logger logger{std::make_unique<ActionLog>([&] { thrower.reset(); }, entries)};
+    ChainParams params{hex_string_to_byte_vec("51")};
+    BOOST_CHECK(!thrower);
+    BOOST_CHECK_EQUAL(entries, 1);
